const $=id=>document.getElementById(id), canvas=$('board'), ctx=canvas.getContext('2d');
const types=['fire','nature','earth','light','dark','water'];
const colors=['#ff9363','#b6ed73','#d3b083','#ffe79c','#c39bfa','#74d9ef'];
const icons=['♨','❋','◆','✧','☽','≈'];
const path=[[0,135],[195,135],[195,315],[460,315],[460,135],[710,135],[710,455],[390,455],[390,570],[900,570]];
const pads=[[105,225],[285,210],[285,400],[390,225],[545,225],[625,340],[805,250],[805,450],[500,530],[230,525]];
let gold,lives,wave,towers,enemies,shots,active,paused,speed,spawned,spawnClock,tickClock,seq,tab='build',combat='',scripts={},runner=null,pending=false,generation=0,last=performance.now(),finished=false;
const examples={build:'// Build your first elemental defense.\nconst startingElement = "fire";\nbuild(startingElement, 1);\nbuild("water", 2);\nbuild("nature", 4);\n\n// After earning gold, try:\n// upgrade(1, "water");',combat:'// Attack the enemy closest to the crystal.\nfor (const tower of towers) {\n  const inRange = enemies.filter(enemy =>\n    distance(tower, enemy) <= tower.range\n  );\n  inRange.sort((a, b) => b.progress - a.progress);\n  if (inRange.length > 0) {\n    attack(tower.id, inRange[0].id);\n  }\n}'};
function log(text){const lines=$('log').textContent.split('\n');lines.push(text);$('log').textContent=lines.slice(-40).join('\n');$('log').scrollTop=10000;}
function reset(){generation++;if(runner)runner.terminate();runner=null;pending=false;gold=240;lives=20;wave=0;towers=[];enemies=[];shots=[];active=false;paused=false;speed=1;seq=0;finished=false;combat='';scripts={...examples};$('code').value=scripts[tab];$('log').textContent='Ready. Apply your build script to begin.';$('pause').textContent='Pause';$('speed').textContent='1× speed';$('banner').textContent='Write your strategy. Defend the crystal.';update();}
function update(){ $('gold').textContent=gold;$('lives').textContent=lives;$('wave').textContent=wave+' / 12';$('start').disabled=active||finished;$('start').textContent=finished?'Run complete':active?'Wave in progress':'▶ Start wave '+(wave+1);$('objectives').innerHTML=(towers.length>=3?'✓':'○')+' Build three towers<br>'+(combat?'✓':'○')+' Apply a combat script<br>'+(towers.some(t=>t.level>1)?'✓':'○')+' Upgrade a tower';}
function snapshot(){return {gold,wave,towers:towers.map(({cool,...t})=>t),enemies:enemies.map(e=>({...e}))};}
function execute(code,mode){if(pending)return;pending=true;const g=generation;runner=new Worker('runner.js');const thisWorker=runner;const timeout=setTimeout(()=>{thisWorker.terminate();if(g!==generation)return;pending=false;runner=null;log('Script stopped: exceeded 1 second. Check for an infinite loop.');if(mode==='combat')combat='';},1000);thisWorker.onmessage=({data})=>{clearTimeout(timeout);thisWorker.terminate();if(g!==generation)return;pending=false;runner=null;if(data.error){log('Error: '+data.error);if(mode==='combat')combat='';return;}if(mode==='validate'){combat=code;log('Combat script applied. Your code now controls targeting.');}else for(const a of data.actions)apply(a,mode);for(const line of data.logs)log('› '+line);update();};thisWorker.onerror=e=>{clearTimeout(timeout);thisWorker.terminate();pending=false;log('Worker error: '+e.message);};thisWorker.postMessage({code,state:snapshot(),mode});}
function apply(a,mode){if(a.type==='attack'&&mode==='combat'){const t=towers.find(t=>t.id===a.tower),e=enemies.find(e=>e.id===a.enemy);if(t&&e)attack(t,e);return;}if(mode!=='build')return;const pad=Number(a.pad),t=towers.find(t=>t.pad===pad);if(!Number.isInteger(pad)||pad<1||pad>10)return log('Choose a pad from 1 to 10.');if(a.type==='build'){if(!types.includes(a.element))return log('Unknown element: '+a.element);if(t)return log('Pad '+pad+' is occupied. Try upgrade('+pad+').');if(gold<60)return log('Need 60 gold to build.');gold-=60;const [x,y]=pads[pad-1];towers.push({id:++seq,pad,x,y,element:a.element,secondary:null,level:1,range:160,cool:0,spent:60});log('Built '+a.element+' tower on pad '+pad+'.');}if(a.type==='upgrade'){if(!t)return log('No tower on pad '+pad+'.');if(t.level>=3)return log('Tower is already level 3.');if(a.element&&(!types.includes(a.element)||a.element===t.element))return log('Choose a different valid secondary element.');const cost=80*t.level;if(gold<cost)return log('Upgrade needs '+cost+' gold.');gold-=cost;t.spent+=cost;t.level++;t.range+=25;if(a.element)t.secondary=a.element;log('Pad '+pad+' upgraded to level '+t.level+'.');}if(a.type==='sell'&&t){gold+=Math.floor(t.spent*.6);towers=towers.filter(v=>v!==t);log('Sold tower on pad '+pad+'.');}}
function modifier(element,enemy){const i=types.indexOf(element),j=types.indexOf(enemy);return j===(i+1)%6?1.6:j===(i+5)%6?.65:1;}
function attack(t,e){if(t.cool>0||e.hp<=0||Math.hypot(t.x-e.x,t.y-e.y)>t.range)return;const mult=Math.max(modifier(t.element,e.element),t.secondary?modifier(t.secondary,e.element):0);e.hp-=15*t.level*mult;t.cool=.6;shots.push({x:t.x,y:t.y,tx:e.x,ty:e.y,color:colors[types.indexOf(t.element)],ttl:.16});}
function start(){if(active||finished)return;wave++;active=true;spawned=0;spawnClock=0;tickClock=0;$('banner').textContent='Wave '+wave+' · '+types[(wave-1)%6]+' invaders';log('Wave '+wave+' started.');update();}
function position(e){let remaining=e.progress;for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],d=Math.hypot(b[0]-a[0],b[1]-a[1]);if(remaining<=d){e.x=a[0]+(b[0]-a[0])*remaining/d;e.y=a[1]+(b[1]-a[1])*remaining/d;return false;}remaining-=d;}return true;}
function step(dt){if(!active||paused||finished)return;spawnClock-=dt;tickClock+=dt;const count=7+wave*2;if(spawned<count&&spawnClock<=0){const hp=45+wave*19;const e={id:++seq,element:types[(wave-1)%6],hp,maxHp:hp,progress:0,x:0,y:135};enemies.push(e);spawned++;spawnClock=.7;}for(const t of towers)t.cool=Math.max(0,t.cool-dt);for(const e of enemies){if(e.hp<=0){gold+=9+wave;continue;}e.progress+=dt*(42+wave*2);if(position(e)){e.escaped=true;lives--;}}enemies=enemies.filter(e=>e.hp>0&&!e.escaped);if(combat){if(tickClock>=.25&&!pending){tickClock=0;execute(combat,'combat');}}else for(const t of towers){const candidates=enemies.filter(e=>Math.hypot(t.x-e.x,t.y-e.y)<=t.range).sort((a,b)=>b.progress-a.progress);if(candidates[0])attack(t,candidates[0]);}if(lives<=0){lives=0;active=false;finished=true;$('banner').textContent='Crystal lost. Revise your strategy and try again.';log('Defeat at wave '+wave+'.');}else if(spawned===count&&enemies.length===0){active=false;gold+=45+wave*5;finished=wave===12;$('banner').textContent=finished?'Victory! Your code held the frontier.':'Wave cleared · Build or upgrade before the next wave.';log('Wave cleared! Bonus '+(45+wave*5)+' gold.');}update();}
function circle(x,y,r,color){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}
function draw(dt){ctx.fillStyle='#17291f';ctx.fillRect(0,0,900,600);for(let x=20;x<900;x+=43)for(let y=25;y<600;y+=47){const n=Math.sin(x*32+y*17);circle(x+n*8,y,2,'#2c402d');}ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();path.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.strokeStyle='#45503b';ctx.lineWidth=64;ctx.stroke();ctx.strokeStyle='#677052';ctx.lineWidth=48;ctx.stroke();ctx.setLineDash([3,18]);ctx.strokeStyle='#84907155';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([]);for(let i=0;i<pads.length;i++){const [x,y]=pads[i];circle(x,y,29,'#20372b');ctx.beginPath();ctx.arc(x,y,28,0,7);ctx.strokeStyle='#55754b';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#99b58c';ctx.font='13px monospace';ctx.textAlign='center';ctx.fillText(i+1,x,y+5);}for(const t of towers){const c=colors[types.indexOf(t.element)];circle(t.x,t.y,23,'#0c201b');ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(t.x,t.y-22);ctx.lineTo(t.x+17,t.y+8);ctx.lineTo(t.x,t.y+20);ctx.lineTo(t.x-17,t.y+8);ctx.closePath();ctx.fill();if(t.secondary)circle(t.x+15,t.y-15,7,colors[types.indexOf(t.secondary)]);ctx.fillStyle='#10291e';ctx.font='bold 15px monospace';ctx.fillText(t.level,t.x,t.y+6);}for(const e of enemies){circle(e.x,e.y,12,colors[types.indexOf(e.element)]);circle(e.x-3,e.y-3,3,'#ffffff88');ctx.fillStyle='#0b171c';ctx.fillRect(e.x-16,e.y-24,32,4);ctx.fillStyle='#c7ed93';ctx.fillRect(e.x-16,e.y-24,32*Math.max(0,e.hp/e.maxHp),4);}shots=shots.filter(s=>s.ttl>0);for(const s of shots){s.ttl-=dt;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.tx,s.ty);ctx.strokeStyle=s.color;ctx.lineWidth=3;ctx.stroke();}ctx.save();ctx.translate(860,565);ctx.shadowColor='#9bedcf';ctx.shadowBlur=22;ctx.fillStyle='#a0eacb';ctx.beginPath();ctx.moveTo(0,-28);ctx.lineTo(18,0);ctx.lineTo(0,25);ctx.lineTo(-18,0);ctx.closePath();ctx.fill();ctx.restore();}
function frame(now){const dt=Math.min((now-last)/1000,.05)*speed;last=now;step(dt);draw(dt);requestAnimationFrame(frame);}
$('elements').innerHTML=types.map((t,i)=>'<div class="element"><b style="color:'+colors[i]+'">'+icons[i]+'</b>'+t[0].toUpperCase()+t.slice(1)+'<small>60 gold</small></div>').join('');
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{scripts[tab]=$('code').value;tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('code').value=scripts[tab];$('context').textContent=tab==='build'?'Runs once when you apply it. Build on numbered pads.':'Runs every 250ms during battle. Pick targets within range.';$('run').textContent=tab==='build'?'▷ Apply build script':'▷ Apply combat script';});
$('run').onclick=()=>{scripts[tab]=$('code').value;execute(scripts[tab],tab==='build'?'build':'validate');};$('example').onclick=()=>{$('code').value=examples[tab];};$('start').onclick=start;$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause';};$('speed').onclick=()=>{speed=speed===1?2:1;$('speed').textContent=speed+'× speed';};$('reset').onclick=reset;$('clear').onclick=()=>{$('log').textContent='';};$('help').onclick=()=>$('docs').showModal();$('close').onclick=()=>$('docs').close();$('code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('  ',start,end,'end');}};
canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*900/r.width,y=(e.clientY-r.top)*600/r.height;const i=pads.findIndex(p=>Math.hypot(p[0]-x,p[1]-y)<35);if(i>=0){const t=towers.find(t=>t.pad===i+1);log(t?'Pad '+t.pad+': '+t.element+(t.secondary?' + '+t.secondary:'')+', level '+t.level+'. Upgrade cost '+80*t.level+'.':'Pad '+(i+1)+' is empty. Try build("fire", '+(i+1)+');');}};
reset();requestAnimationFrame(frame);
